INSERT INTO faqs(id,question,answer,active,sort_order) SELECT 'solutions','Sách và tài liệu có đáp án không?','Phân dạng Toán 6–9: sách học sinh không kèm đáp án; phụ huynh nhận file mềm đầy đủ đề và đáp án. 70 đề bứt tốc: đáp án chi tiết nhận qua mã QR trong sách. Toán 3 Nâng cao theo tuần và bộ 10 đề học kì I có đáp án. Liên hệ trợ lí để xác nhận cách nhận đáp án của bộ Em là siêu nhân.',1,1 WHERE NOT EXISTS(SELECT 1 FROM schema_versions WHERE version=10) ON CONFLICT(id) DO UPDATE SET question=excluded.question,answer=excluded.answer,active=1,sort_order=excluded.sort_order;
INSERT INTO faqs(id,question,answer,active,sort_order) SELECT 'delivery','Phí vận chuyển và thời gian giao thế nào?','70 đề bứt tốc đặt trước được miễn phí vận chuyển. Với các sách khác, trợ lí báo phí và thời gian giao theo địa chỉ trước khi gửi đơn.',1,2 WHERE NOT EXISTS(SELECT 1 FROM schema_versions WHERE version=10) ON CONFLICT(id) DO UPDATE SET question=excluded.question,answer=excluded.answer,active=1,sort_order=excluded.sort_order;
INSERT INTO faqs(id,question,answer,active,sort_order) SELECT 'digital-delivery','Tài liệu PDF đầy đủ nhận bằng cách nào?','Bản đọc thử được xem và tải miễn phí trên website. Để mua tài liệu đầy đủ, nhắn Zalo trợ lí 0365 473 632 để xác nhận giá, thanh toán và cách nhận file trước khi mua.',1,3 WHERE NOT EXISTS(SELECT 1 FROM schema_versions WHERE version=10) ON CONFLICT(id) DO UPDATE SET question=excluded.question,answer=excluded.answer,active=1,sort_order=excluded.sort_order;
INSERT INTO faqs(id,question,answer,active,sort_order) SELECT 'foundation','Con đang mất gốc nên chọn sách nào?','Xem bản đọc thử rồi gọi cô Nga 0989 066 885 hoặc trợ lí 0365 473 632 để được tư vấn tài liệu phù hợp với kiến thức hiện tại của con.',1,4 WHERE NOT EXISTS(SELECT 1 FROM schema_versions WHERE version=10) ON CONFLICT(id) DO UPDATE SET question=excluded.question,answer=excluded.answer,active=1,sort_order=excluded.sort_order;
INSERT INTO faqs(id,question,answer,active,sort_order) SELECT 'club-gift','Học sinh đang học tại CLB có ưu đãi gì?','Học sinh đang học tại CLB được tặng trọn bộ 10 đề chinh phục cuối học kì I – Toán 3. Liên hệ trợ lí để nhận tài liệu.',1,5 WHERE NOT EXISTS(SELECT 1 FROM schema_versions WHERE version=10) ON CONFLICT(id) DO UPDATE SET question=excluded.question,answer=excluded.answer,active=1,sort_order=excluded.sort_order;
INSERT INTO faqs(id,question,answer,active,sort_order) SELECT 'offline','Con có thể học trực tiếp tại CLB không?','CLB dạy trực tiếp cho học sinh lớp 3–9 tại Geleximco, Lê Trọng Tấn. Đăng ký tư vấn trên trang STEM Maths để CLB xác nhận lớp, lịch và học phí trước khi học.',1,6 WHERE NOT EXISTS(SELECT 1 FROM schema_versions WHERE version=10) ON CONFLICT(id) DO UPDATE SET question=excluded.question,answer=excluded.answer,active=1,sort_order=excluded.sort_order;
